script:
(function () {
  // Nothing in here is specific to any one company. The block reads the
  // signed-in user's default company, falls back to the only company on the
  // site, and takes its currency from the Company record itself.
  var root = (typeof root_element !== 'undefined' && root_element) ? root_element : document;
  var scope = root.querySelector ? root : document;

  function cell(key) { return scope.querySelector('[data-ps-kpi="' + key + '"]'); }

  function paint(key, text) {
    var el = cell(key);
    if (!el) return;
    el.textContent = text;
    el.classList.remove('is-loading');
  }

  function getList(doctype, filters, fields) {
    return frappe.call({
      method: 'frappe.client.get_list',
      args: { doctype: doctype, filters: filters, fields: fields, limit_page_length: 0 }
    }).then(function (r) { return (r && r.message) || []; });
  }

  function getValue(doctype, name, field) {
    return frappe.call({
      method: 'frappe.client.get_value',
      args: { doctype: doctype, filters: { name: name }, fieldname: field }
    }).then(function (r) { return (r && r.message && r.message[field]) || null; });
  }

  function sum(rows, field) {
    var t = 0;
    for (var i = 0; i < rows.length; i++) { t += parseFloat(rows[i][field]) || 0; }
    return t;
  }

  function resolveCompany() {
    var c = frappe.defaults.get_user_default('Company');
    if (c) { return Promise.resolve(c); }
    return getList('Company', {}, ['name']).then(function (rows) {
      return rows.length ? rows[0].name : null;
    });
  }

  resolveCompany().then(function (company) {
    if (!company) {
      paint('company', 'No company set up yet');
      paint('units', 'n/a'); paint('occupancy', 'n/a');
      paint('rentroll', 'n/a'); paint('arrears', 'n/a');
      return;
    }

    paint('company', company);

    var currency = null;
    var pending = [];

    function money(n) {
      var prefix = currency ? (currency + ' ') : '';
      return prefix + Math.round(n || 0).toLocaleString('en-US');
    }

    function later(fn) {
      if (currency !== null) { fn(); } else { pending.push(fn); }
    }

    getValue('Company', company, 'default_currency').then(function (c) {
      currency = c || '';
      pending.forEach(function (fn) { fn(); });
      pending = [];
    }).catch(function () {
      currency = '';
      pending.forEach(function (fn) { fn(); });
      pending = [];
    });

    // Units and occupancy, scoped by the properties belonging to this company.
    getList('PS Property', { company: company }, ['name']).then(function (props) {
      var names = props.map(function (p) { return p.name; });
      if (!names.length) {
        paint('units', '0'); paint('occupancy', '0%');
        return;
      }
      return getList('Property Unit', { property: ['in', names] }, ['name', 'unit_status'])
        .then(function (units) {
          var total = units.length;
          var occupied = units.filter(function (u) { return u.unit_status === 'Occupied'; }).length;
          paint('units', total.toLocaleString('en-US'));
          paint('occupancy', total ? Math.round((occupied / total) * 100) + '%' : '0%');
        });
    }).catch(function (e) {
      console.error('ps-hero: units/occupancy failed', e);
      paint('units', 'n/a'); paint('occupancy', 'n/a');
    });

    getList('PS Lease Agreement', {
      company: company, docstatus: 1,
      lease_status: ['in', ['Active', 'Expiring Soon']]
    }, ['rent_amount']).then(function (rows) {
      var v = sum(rows, 'rent_amount');
      later(function () { paint('rentroll', money(v)); });
    }).catch(function (e) {
      console.error('ps-hero: rent roll failed', e);
      paint('rentroll', 'n/a');
    });

    getList('Sales Invoice', {
      company: company, docstatus: 1,
      status: ['in', ['Overdue', 'Unpaid']]
    }, ['outstanding_amount']).then(function (rows) {
      var v = sum(rows, 'outstanding_amount');
      later(function () { paint('arrears', money(v)); });
    }).catch(function (e) {
      console.error('ps-hero: arrears failed', e);
      paint('arrears', 'n/a');
    });
  });
})();

style:
.ps-hero {
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  width: 100%;
  max-width: 100%;
  padding: 28px;
  border-radius: 10px;
  background-color: #0b6b3a;
  background-image: linear-gradient(135deg, #0b6b3a 0%, #0a5c31 40%, #08301b 100%);
  box-shadow: 0 10px 28px rgba(8,48,27,0.24), 0 1px 2px rgba(8,48,27,0.30);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto, "Helvetica Neue", Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
}
.ps-hero * { box-sizing: border-box; }
.ps-hero .ps-hero__glow {
  position: absolute;
  top: -55%;
  right: -12%;
  width: 620px;
  height: 620px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255,255,255,0.12) 0%, rgba(255,255,255,0.04) 45%, rgba(255,255,255,0) 70%);
  pointer-events: none;
}
.ps-hero .ps-hero__inner {
  position: relative;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 24px 32px;
}
.ps-hero .ps-hero__brand { min-width: 0; }
.ps-hero .ps-hero__title {
  margin: 0;
  font-size: 24px;
  line-height: 1.15;
  font-weight: 650;
  letter-spacing: -0.02em;
  color: #ffffff;
}
.ps-hero .ps-hero__rule {
  display: block;
  width: 44px;
  height: 3px;
  margin: 12px 0 10px;
  border-radius: 2px;
  background: #c0392b;
}
.ps-hero .ps-hero__sub {
  margin: 0;
  font-size: 13px;
  line-height: 1.4;
  font-weight: 400;
  letter-spacing: 0.01em;
  color: rgba(255,255,255,0.70);
}
.ps-hero .ps-hero__kpis {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 18px 0;
  min-width: 0;
}
.ps-hero .ps-hero__kpi {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 2px 20px;
  min-width: 0;
  border-left: 1px solid rgba(255,255,255,0.16);
}
.ps-hero .ps-hero__kpi:first-child { border-left: 0; padding-left: 0; }
.ps-hero .ps-hero__kpi:last-child { padding-right: 0; }
.ps-hero .ps-hero__label {
  font-size: 10px;
  line-height: 1.2;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  white-space: nowrap;
  color: rgba(255,255,255,0.58);
}
.ps-hero .ps-hero__value {
  font-size: 22px;
  line-height: 1.1;
  font-weight: 640;
  letter-spacing: -0.015em;
  white-space: nowrap;
  color: #ffffff;
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1;
}
.ps-hero .ps-hero__value.is-loading {
  color: rgba(255,255,255,0.35);
  animation: ps-hero-pulse 1.4s ease-in-out infinite;
}
@keyframes ps-hero-pulse {
  0%, 100% { opacity: 0.45; }
  50% { opacity: 0.85; }
}
@media (max-width: 1100px) {
  .ps-hero .ps-hero__value { font-size: 20px; }
  .ps-hero .ps-hero__kpi { padding: 2px 16px; }
}
@media (max-width: 860px) {
  .ps-hero { padding: 22px; }
  .ps-hero .ps-hero__inner { align-items: flex-start; }
  .ps-hero .ps-hero__kpis { width: 100%; gap: 20px 0; }
  .ps-hero .ps-hero__kpi {
    flex: 1 1 45%;
    padding: 0 14px;
    border-left: 0;
    border-top: 0;
  }
  .ps-hero .ps-hero__kpi:nth-child(odd) { padding-left: 0; }
  .ps-hero .ps-hero__label { white-space: normal; }
}
@media (max-width: 480px) {
  .ps-hero .ps-hero__title { font-size: 21px; }
  .ps-hero .ps-hero__kpi { flex: 1 1 100%; padding: 0; }
  .ps-hero .ps-hero__value { font-size: 19px; }
}
